using UnityEngine;
using Xunit;

namespace OniMoono.Tests
{
    /// Matrix4x4.Inverse3DAffine and Rotate, and Camera's rects, matrices and conversions,
    /// against the original player (tools/UnityProbe ProjectionMath.cs, PROBE_SCENARIO=projection;
    /// pj-check.py rule reproduces every logged case): the random cases' first ones, the
    /// degenerate ones, and the rect rules' every case. Float bits in hex, matrices row-major.
    /// The cameras render to the headless screen, 1024 × 768 as in the probe's runs.
    public class CameraMathTests : EngineTest
    {
        static float[] Bits(string hex) => System.Array.ConvertAll(hex.Split(','), h => System.BitConverter.Int32BitsToSingle(System.Convert.ToInt32(h, 16)));

        static string Hex(params float[] v) => string.Join(",", System.Array.ConvertAll(v, f => System.BitConverter.SingleToInt32Bits(f).ToString("x8")));

        static string Hex(Vector3 v) => Hex(v.x, v.y, v.z);
        static string Hex(Rect r) => Hex(r.x, r.y, r.width, r.height);
        static string Hex(Ray r) => Hex(r.origin) + "," + Hex(r.direction);

        static string Hex(Matrix4x4 m)
        {
            var e = new float[16];
            for (int i = 0; i < 16; i++) e[i] = m[i / 4, i % 4];
            return Hex(e);
        }

        static Matrix4x4 Rows(string hex)
        {
            var v = Bits(hex);
            var m = new Matrix4x4();
            for (int i = 0; i < 16; i++) m[i / 4, i % 4] = v[i];
            return m;
        }

        static Vector3 V3(string hex)
        {
            var v = Bits(hex);
            return new Vector3(v[0], v[1], v[2]);
        }

        static Rect R(string hex)
        {
            var v = Bits(hex);
            return new Rect(v[0], v[1], v[2], v[3]);
        }

        static Camera NewCamera()
        {
            Assert.Equal(1024, Screen.width);
            Assert.Equal(768, Screen.height);
            var camera = new GameObject("Camera").AddComponent<Camera>();
            camera.enabled = false;
            return camera;
        }

        // The NaNs of a NaN input differ in sign (the native code's operand order).
        static string AnyNaN(string hex) => System.Text.RegularExpressions.Regex.Replace(hex, "[7f]fc00000", "nan");

