        public void Inverse3DAffineIsTheOriginals(string input, bool ok, string expected)
        {
            var m = Rows(input);
            var r = Rows("40e00000,40e00000,40e00000,40e00000,40e00000,40e00000,40e00000,40e00000,40e00000,40e00000,40e00000,40e00000,40e00000,40e00000,40e00000,40e00000");
            Assert.Equal(ok, Matrix4x4.Inverse3DAffine(m, ref r));
            Assert.Equal(AnyNaN(expected), AnyNaN(Hex(r)));
            var r2 = Matrix4x4.identity;
            Assert.Equal(ok, Matrix4x4.Inverse3DAffine(in m, ref r2));
            Assert.Equal(AnyNaN(expected), AnyNaN(Hex(r2)));
        }

