        /// A set aspect stays, whatever its value, through rect, pixel rect, projection and field
        /// of view changes, until ResetAspect.
        [Fact]
        public void TheSetAspectStaysUntilReset()
        {
            var camera = NewCamera();
            Assert.Equal("3faaaaab", Hex(camera.aspect));
            camera.aspect = 2;
            camera.rect = new Rect(0.1f, 0.1f, 0.5f, 0.5f);
            camera.pixelRect = new Rect(10, 10, 300, 100);
            camera.orthographic = true;
            camera.orthographic = false;
            camera.fieldOfView = 50;
            Assert.Equal("40000000", Hex(camera.aspect));
            Assert.Equal("41200000,41200000,43960000,42c80001", Hex(camera.pixelRect));
            camera.ResetAspect();
            Assert.Equal("403fffff", Hex(camera.aspect));
            Assert.Equal("3f36ff78", Hex(camera.projectionMatrix.m00));
            camera.aspect = 0;
            Assert.Equal("7f800000", Hex(camera.projectionMatrix.m00));
            camera.aspect = -1.5f;
            Assert.Equal("bfb6ff77", Hex(camera.projectionMatrix.m00));
            camera.aspect = float.NaN;
            Assert.True(float.IsNaN(camera.aspect));
            camera.aspect = float.PositiveInfinity;
            Assert.Equal("00000000", Hex(camera.projectionMatrix.m00));
            camera.ResetAspect();
            camera.rect = new Rect(0.3f, 0.3f, 0.5f, 0);
            Assert.Equal("3f800000", Hex(camera.aspect));
            camera.rect = new Rect(0.3f, 0.3f, 0, 0.5f);
            Assert.Equal("00000000", Hex(camera.aspect));
        }

        static Camera Setup(int id, bool ortho, string settings, bool setAspect, string rect, string pos, string rot, string scale)
        {
            var camera = NewCamera();
            var s = Bits(settings);
            camera.orthographic = ortho;
            camera.orthographicSize = s[0];
            camera.fieldOfView = s[1];
            camera.nearClipPlane = s[2];
            camera.farClipPlane = s[3];
            camera.rect = R(rect);
            if (setAspect) camera.aspect = s[4];
            else camera.ResetAspect();
            var t = camera.transform;
            t.position = V3(pos);
            var q = Bits(rot);
            t.rotation = new Quaternion(q[0], q[1], q[2], q[3]);
            t.localScale = V3(scale);
