        [InlineData(31, "c42e7132,3f155303,c2c27850", "4412503e,43e0f15e,4463a9b5", "3ede1cd2,3f28d2d0,4463a9b5", "43adde76,42850821,bf316c81", "3e3779d8,bc9cb5e4,bf316c81", "c3c887c9,c34b6786,c47c251a", "c450f107,c327116a,c47c251a", "3f24a07c,3f31a8ed,4463a9b5", "43ef0e69,43d7aa26,4463a9b5", "c42e05d5,bf00e392,c2d13e82,3e9b5c3b,be55b10a,bf6e020a", "c42ed257,be720b10,c2d13e82,be166326,be37d520,bf7904cb")]
        public void ConversionsAreTheOriginals(int id, string world, string screen, string viewport, string w2s, string w2v, string s2w, string v2w, string s2v, string v2s, string sray, string vray)
        {
            Camera camera = null;
            foreach (var row in Cameras)
                if ((int)row[0] == id)
                    camera = Setup(id, (bool)row[1], (string)row[2], (bool)row[3], (string)row[4], (string)row[5], (string)row[6], (string)row[7]);
            Assert.NotNull(camera);
            Assert.Equal(w2s, Hex(camera.WorldToScreenPoint(V3(world))));
            Assert.Equal(w2v, Hex(camera.WorldToViewportPoint(V3(world))));
            Assert.Equal(s2w, Hex(camera.ScreenToWorldPoint(V3(screen))));
            Assert.Equal(v2w, Hex(camera.ViewportToWorldPoint(V3(viewport))));
            Assert.Equal(s2v, Hex(camera.ScreenToViewportPoint(V3(screen))));
            Assert.Equal(v2s, Hex(camera.ViewportToScreenPoint(V3(viewport))));
            var ray = camera.ScreenPointToRay(V3(screen));
            var vr = camera.ViewportPointToRay(V3(viewport));
            Assert.Equal(sray[..26], Hex(ray.origin));
            Assert.Equal(vray[..26], Hex(vr.origin));
            if (camera.orthographic)
            {
                Assert.Equal(sray, Hex(ray));
                Assert.Equal(vray, Hex(vr));
            }
        }

        /// ScreenToWorldPoint gives zero, and the rays start at the camera along +z, where the
        /// depth-0.95 point lies under 1e-6 in front of the camera (an empty viewport, a zero or
        /// NaN aspect, clip planes close to the camera).
        [Fact]
        public void TheUnprojectionGivesUpAsTheOriginal()
        {
            var camera = NewCamera();
            var t = camera.transform;
            var center = new Vector3(512, 384, 5);
            camera.nearClipPlane = System.BitConverter.Int32BitsToSingle(0x34bbe7a4);
            camera.farClipPlane = 3 * camera.nearClipPlane;
            Assert.Equal("c08a968f,bff733bf,40e00000", Hex(camera.ScreenToWorldPoint(new Vector3(100.5f, 200.5f, 7))));
            camera.nearClipPlane = System.BitConverter.Int32BitsToSingle(0x34bbe7a3);
            camera.farClipPlane = 3 * camera.nearClipPlane;
            Assert.Equal("00000000,00000000,00000000", Hex(camera.ScreenToWorldPoint(center)));
            camera.orthographic = true;
            camera.nearClipPlane = -System.BitConverter.Int32BitsToSingle(0x358d4825);
            camera.farClipPlane = System.BitConverter.Int32BitsToSingle(0x358d4825);
            Assert.Equal("c0ab7556,c018eaaa,40e00000", Hex(camera.ScreenToWorldPoint(new Vector3(100.5f, 200.5f, 7))));
            camera.nearClipPlane = -System.BitConverter.Int32BitsToSingle(0x358d4824);
            camera.farClipPlane = System.BitConverter.Int32BitsToSingle(0x358d4824);
            Assert.Equal("00000000,00000000,00000000", Hex(camera.ScreenToWorldPoint(center)));

            camera.orthographic = false;
            camera.nearClipPlane = 0.3f;
            camera.farClipPlane = 1000;
            t.position = new Vector3(1, 2, 3);
            t.rotation = Quaternion.Euler(0, 90, 0);
            camera.rect = new Rect(0.3f, 0.3f, 0, 0.5f);
            var p = new Vector3(100.5f, 200.5f, 7);
            Assert.Equal("00000000,00000000,00000000", Hex(camera.ScreenToWorldPoint(p)));
            Assert.Equal("3f800000,40000000,40400000,00000000,00000000,3f800000", Hex(camera.ScreenPointToRay(p)));
            Assert.Equal("3f800000,40000000,40400000,00000000,00000000,3f800000", Hex(camera.ViewportPointToRay(new Vector3(0.3f, 0.6f, 7))));
            camera.orthographic = true;
            Assert.Equal("3f800000,40000000,40400000,00000000,00000000,3f800000", Hex(camera.ScreenPointToRay(p)));
            camera.rect = new Rect(0, 0, 1, 1);
            camera.orthographic = false;
            camera.aspect = 0;
            Assert.Equal("00000000,00000000,00000000", Hex(camera.ScreenToWorldPoint(p)));
        }
    }
